  @Override
  public List<SelectDictVO> findAllByNameOrCode(String name, String code) {
    BooleanBuilder bb = new BooleanBuilder();
    bb.and(QSelectDict.selectDict.validStatus.eq(ValidStatus.VALID));
    Optional.ofNullable(name)
        .ifPresent(n -> bb.or(QSelectDict.selectDict.name.like("%" + n + "%")));
    Optional.ofNullable(code)
        .ifPresent(c -> bb.or(QSelectDict.selectDict.code.like("%" + c + "%")));
    Iterable<SelectDict> all = selectDictRepository.findAll(bb);
    return Streams.stream(all).map(entity -> new SelectDictVO(entity)).collect(Collectors.toList());
  }

  /**
   * 根据字典ID获取值列表
   * @param dictId
   * @return
   */
  @Override
  public List<CodeValue> getValueListById(Long dictId) {
    Optional<SelectDict> dict = selectDictRepository.findById(dictId);
    if(!dict.isPresent()){
      return Collections.EMPTY_LIST;
    }
    if(Objects.equals(DictType.SELECT_LIST, dict.get().getDictType())){
      return dict.get().getSelectValues();
    }
    try{
      //这里只能采取约定大于配置的方式，字典接口返回统一的格式
      if(Objects.equals(DictType.HTTP_INVOKE, dict.get().getDictType())){
        JsonObject object = restTemplate.getForObject(dict.get().getHttpUrl(), JsonObject.class);
        List<CodeValue> result = (List<CodeValue>) object.getResult();
        return result;
      }
    }catch (Exception e){
      log.error("请求接口异常", e);
      return Collections.EMPTY_LIST;
    }

    return Collections.EMPTY_LIST;
  }
